mapper.select:
SELECT DISTINCT m.* FROM t_menu m INNER JOIN t_role_menu rm ON m.id = rm.menu_id INNER JOIN t_employee_role er ON rm.role_id = er.role_id WHERE er.employee_id = #{employeeId} AND m.is_delete = 0 AND m.status = 0 AND m.visible = 0
AND m.platform = #{platform}
ORDER BY m.sort_order ASC
